alter table _starting_grid_seed enable row level security;
do $$ begin
 if (select count(*) from _starting_grid_seed s join public.people p on p.slug=s.person_slug join public.f1_team_facts t on t.slug=s.team_slug)<>23 then
 raise exception 'Starting grid identities missing: expected 23 contracts';end if;
end $$;
insert into public.f1_starting_grid_datasets(id,season,as_of_date,description)
values('f1-2027-starting-grid-2026-10-26-v1',2027,'2026-10-26','19 confirmed race seats plus Bearman, Lawson and Lindblad retained as game assumptions. Published terms are separate from operational game terms.') on conflict(id) do nothing;
insert into public.f1_starting_driver_contracts
select 'f1-2027-starting-grid-2026-10-26-v1'||':'||s.person_slug||':'||s.role,'f1-2027-starting-grid-2026-10-26-v1',p.id,t.id,s.driver_id,s.role,s.slot_number,s.seat_basis,s.reference_status,s.reference_confirmed_through,s.reference_exact_end,s.start_season,s.end_season,s.term_basis,s.annual_salary_usd_cents,s.salary_basis,s.source_url,s.seat_source_url,s.notes
from _starting_grid_seed s join public.people p on p.slug=s.person_slug join public.f1_team_facts t on t.slug=s.team_slug
on conflict(id) do nothing;
insert into public.f1_starting_team_slots
select 'f1-2027-starting-grid-2026-10-26-v1',t.id,r.role,n.slot_number,c.person_id,c.id
from public.f1_team_facts t cross join (values('race_driver'),('reserve_driver')) r(role) cross join (values(1),(2)) n(slot_number)
left join public.f1_starting_driver_contracts c on c.dataset_id='f1-2027-starting-grid-2026-10-26-v1' and c.team_id=t.id and c.role=r.role and c.slot_number=n.slot_number
where t.slug in(select team_slug from _starting_grid_seed)
on conflict(dataset_id,team_id,role,slot_number) do nothing;
do $$ declare table_name text; begin
 foreach table_name in array array['f1_starting_grid_datasets','f1_starting_driver_contracts','f1_starting_team_slots'] loop
 execute format('alter table public.%I enable row level security',table_name);
 if not exists(select 1 from pg_policies where schemaname='public' and tablename=table_name and policyname='Public starting grid read') then
 execute format('create policy "Public starting grid read" on public.%I for select to anon,authenticated using(true)',table_name);end if;
 execute format('revoke all on public.%I from anon,authenticated',table_name);
 execute format('grant select on public.%I to anon,authenticated',table_name);
 end loop;
end $$;
create or replace view public.f1_starting_grid_2027 with(security_invoker=true) as
select c.*,p.slug person_slug,p.display_name driver_name,t.slug team_slug,t.short_name team_name
from public.f1_starting_driver_contracts c join public.people p on p.id=c.person_id join public.f1_team_facts t on t.id=c.team_id
where c.dataset_id='f1-2027-starting-grid-2026-10-26-v1';
grant select on public.f1_starting_grid_2027 to anon,authenticated;
do $$ begin
 if (select count(*) from public.f1_starting_driver_contracts where dataset_id='f1-2027-starting-grid-2026-10-26-v1' and role='race_driver')<>22
 or (select count(*) from public.f1_starting_driver_contracts where dataset_id='f1-2027-starting-grid-2026-10-26-v1' and role='race_driver' and seat_basis='confirmed')<>19
 or (select count(*) from public.f1_starting_driver_contracts where dataset_id='f1-2027-starting-grid-2026-10-26-v1' and role='race_driver' and seat_basis='game_assumption')<>3
 or (select count(*) from public.f1_starting_team_slots where dataset_id='f1-2027-starting-grid-2026-10-26-v1')<>44
 then raise exception 'Invalid starting grid: expected 19 confirmed + 3 assumed race seats and 44 total slots';end if;
end $$;
notify pgrst,'reload schema';
commit;
